"use strict";(self.webpackChunkalsritter_blog=self.webpackChunkalsritter_blog||[]).push([[15572],{7168:(e,n,t)=>{t.d(n,{R:()=>i,x:()=>o});var s=t(30758);const r={},a=s.createContext(r);function i(e){const n=s.useContext(a);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:i(e.components),s.createElement(a.Provider,{value:n},e.children)}},87670:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>o,default:()=>u,frontMatter:()=>i,metadata:()=>s,toc:()=>p});const s=JSON.parse('{"id":"AIGC \u76f8\u5173/\u5199\u4e00\u4e2a\u6700\u57fa\u672c\u7684 babyagi","title":"\u5199\u4e00\u4e2a\u6700\u57fa\u672c\u7684 babyagi","description":"","source":"@site/docs/AIGC \u76f8\u5173/\u5199\u4e00\u4e2a\u6700\u57fa\u672c\u7684 babyagi.md","sourceDirName":"AIGC \u76f8\u5173","slug":"/AIGC \u76f8\u5173/\u5199\u4e00\u4e2a\u6700\u57fa\u672c\u7684 babyagi","permalink":"/docs/AIGC \u76f8\u5173/\u5199\u4e00\u4e2a\u6700\u57fa\u672c\u7684 babyagi","draft":false,"unlisted":false,"editUrl":"https://github.com/alsritter/TeaNotes/tree/master/docs/AIGC \u76f8\u5173/\u5199\u4e00\u4e2a\u6700\u57fa\u672c\u7684 babyagi.md","tags":[],"version":"current","lastUpdatedBy":"alsritter.mac","lastUpdatedAt":1757394410000,"frontMatter":{"title":"\u5199\u4e00\u4e2a\u6700\u57fa\u672c\u7684 babyagi","date":"2023-09-27T09:18:36.000Z","tags":[],"categories":[],"updated":"2023-09-27T09:18:36.000Z","cover":"https://image.quicktoolset.top/img/202203022244719.jpg"},"sidebar":"tutorialSidebar","previous":{"title":"\u4f7f\u7528\u725b\u987f\u70ed\u51b7\u5374\u516c\u5f0f\u6a21\u62df\u8bb0\u5fc6","permalink":"/docs/AIGC \u76f8\u5173/\u4f7f\u7528\u725b\u987f\u51b7\u5374\u6a21\u62df\u8bb0\u5fc6"},"next":{"title":"\u52a0\u901f\u63a8\u7406\u5de5\u5177","permalink":"/docs/AIGC \u76f8\u5173/\u52a0\u901f\u63a8\u7406\u5de5\u5177"}}');var r=t(86070),a=t(7168);const i={title:"\u5199\u4e00\u4e2a\u6700\u57fa\u672c\u7684 babyagi",date:new Date("2023-09-27T09:18:36.000Z"),tags:[],categories:[],updated:new Date("2023-09-27T09:18:36.000Z"),cover:"https://image.quicktoolset.top/img/202203022244719.jpg"},o=void 0,l={},p=[];function c(e){const n={code:"code",pre:"pre",...(0,a.R)(),...e.components};return(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-py",children:'import chromadb\nfrom chromadb.utils.embedding_functions import ONNXMiniLM_L6_V2\nimport os\nimport openai\nimport logging\nimport re\nfrom collections import deque\nfrom typing import Dict, List\nimport importlib\nimport time\n\n# Task storage supporting only a single instance of BabyAGI\n# Extensions support begin\n\nOBJECTIVE = "\u4e00\u4e2a\u56e2\u8d2d\u529f\u80fd\u9700\u8981\u8003\u8651\u7684\u70b9"\nJOIN_EXISTING_OBJECTIVE = False\n\n\ndef can_import(module_name):\n    try:\n        importlib.import_module(module_name)\n        return True\n    except ImportError:\n        return False\n\n# Results storage using local ChromaDB\n\n\nclass DefaultResultsStorage:\n    def __init__(self, results_store_name):\n        logging.getLogger(\'chromadb\').setLevel(logging.ERROR)\n        # Create Chroma collection\n        chroma_persist_dir = "chroma"\n        chroma_client = chromadb.PersistentClient(\n            settings=chromadb.config.Settings(\n                persist_directory=chroma_persist_dir,\n            )\n        )\n\n        metric = "cosine"\n        embedding_function = ONNXMiniLM_L6_V2()\n        self.collection = chroma_client.get_or_create_collection(\n            name=results_store_name,\n            metadata={"hnsw:space": metric},\n            embedding_function=embedding_function,\n        )\n\n    def add(self, task: Dict, result: str, result_id: str):\n        # Continue with the rest of the function\n\n        embeddings = None\n        if (\n                len(self.collection.get(\n                    ids=[result_id], include=[])["ids"]) > 0\n        ):  # Check if the result already exists\n            self.collection.update(\n                ids=result_id,\n                embeddings=embeddings,\n                documents=result,\n                metadatas={"task": task["task_name"], "result": result},\n            )\n        else:\n            self.collection.add(\n                ids=result_id,\n                embeddings=embeddings,\n                documents=result,\n                metadatas={"task": task["task_name"], "result": result},\n            )\n\n    def query(self, query: str, top_results_num: int) -> List[dict]:\n        count: int = self.collection.count()\n        if count == 0:\n            return []\n        results = self.collection.query(\n            query_texts=query,\n            n_results=min(top_results_num, count),\n            include=["metadatas"]\n        )\n        return [item["task"] for item in results["metadatas"][0]]\n\n\nclass SingleTaskListStorage:\n    def __init__(self):\n        self.tasks = deque([])\n        self.task_id_counter = 0\n\n    def append(self, task: Dict):\n        self.tasks.append(task)\n\n    def replace(self, tasks: List[Dict]):\n        self.tasks = deque(tasks)\n\n    def popleft(self):\n        return self.tasks.popleft()\n\n    def is_empty(self):\n        return False if self.tasks else True\n\n    def next_task_id(self):\n        self.task_id_counter += 1\n        return self.task_id_counter\n\n    def get_task_names(self):\n        return [t["task_name"] for t in self.tasks]\n\n\ndef use_chroma():\n    print("\\nUsing results storage: " +\n          "\\033[93m\\033[1m" + "Chroma (Default)" + "\\033[0m\\033[0m")\n    return DefaultResultsStorage(\'babyagi_results_table\')\n\n\n# Initialize tasks storage\ntasks_storage = SingleTaskListStorage()\nresults_storage = use_chroma()\n\n\ndef openai_call(\n    prompt: str,\n    max_tokens: int = 100,\n):\n    while True:\n        try:\n            # Use completion API\n            response = openai.ChatCompletion.create(\n                model="gpt-3.5-turbo",\n                messages=[{"role": "user", "content": prompt}],\n                temperature=0.0,\n                max_tokens=max_tokens,\n                top_p=1,\n                frequency_penalty=0,\n                presence_penalty=0,\n            )\n            return response.choices[0].message.content\n        except openai.error.RateLimitError:\n            print(\n                "   *** The OpenAI API rate limit has been exceeded. Waiting 10 seconds and trying again. ***"\n            )\n            time.sleep(10)  # Wait 10 seconds and try again\n        except openai.error.Timeout:\n            print(\n                "   *** OpenAI API timeout occurred. Waiting 10 seconds and trying again. ***"\n            )\n            time.sleep(10)  # Wait 10 seconds and try again\n        except openai.error.APIError:\n            print(\n                "   *** OpenAI API error occurred. Waiting 10 seconds and trying again. ***"\n            )\n            time.sleep(10)  # Wait 10 seconds and try again\n        except openai.error.APIConnectionError:\n            print(\n                "   *** OpenAI API connection error occurred. Check your network settings, proxy configuration, SSL certificates, or firewall rules. Waiting 10 seconds and trying again. ***"\n            )\n            time.sleep(10)  # Wait 10 seconds and try again\n        except openai.error.InvalidRequestError:\n            print(\n                "   *** OpenAI API invalid request. Check the documentation for the specific API method you are calling and make sure you are sending valid and complete parameters. Waiting 10 seconds and trying again. ***"\n            )\n            time.sleep(10)  # Wait 10 seconds and try again\n        except openai.error.ServiceUnavailableError:\n            print(\n                "   *** OpenAI API service unavailable. Waiting 10 seconds and trying again. ***"\n            )\n            time.sleep(10)  # Wait 10 seconds and try again\n        else:\n            break\n\n\ndef task_creation_agent(\n        objective: str, result: Dict, task_description: str, task_list: List[str]\n):\n    prompt = f"""\nYou are to use the result from an execution agent to create new tasks with the following objective: {objective}.\nThe last completed task has the result: \\n{result["data"]}\nThis result was based on this task description: {task_description}.\\n"""\n\n    if task_list:\n        prompt += f"These are incomplete tasks: {\', \'.join(task_list)}\\n"\n    prompt += "Based on the result, return a list of tasks to be completed in order to meet the objective. "\n    if task_list:\n        prompt += "These new tasks must not overlap with incomplete tasks. "\n\n    prompt += """\nReturn one task per line in your response. The result must be a numbered list in the format:\n\n#. First task\n#. Second task\n\nThe number of each entry must be followed by a period. If your list is empty, write "There are no tasks to add at this time."\nUnless your list is empty, do not include any headers before your numbered list or follow your numbered list with any other output."""\n\n    print(f\'\\n*****TASK CREATION AGENT PROMPT****\\n{prompt}\\n\')\n    response = openai_call(prompt, max_tokens=2000)\n    print(f\'\\n****TASK CREATION AGENT RESPONSE****\\n{response}\\n\')\n    new_tasks = response.split(\'\\n\')\n    new_tasks_list = []\n    for task_string in new_tasks:\n        task_parts = task_string.strip().split(".", 1)\n        if len(task_parts) == 2:\n            task_id = \'\'.join(s for s in task_parts[0] if s.isnumeric())\n            task_name = re.sub(r\'[^\\w\\s_]+\', \'\', task_parts[1]).strip()\n            if task_name.strip() and task_id.isnumeric():\n                new_tasks_list.append(task_name)\n            # print(\'New task created: \' + task_name)\n\n    out = [{"task_name": task_name} for task_name in new_tasks_list]\n    return out\n\n\ndef prioritization_agent():\n    task_names = tasks_storage.get_task_names()\n    bullet_string = \'\\n\'\n\n    prompt = f"""\nYou are tasked with prioritizing the following tasks: {bullet_string + bullet_string.join(task_names)}\nConsider the ultimate objective of your team: {OBJECTIVE}.\nTasks should be sorted from highest to lowest priority, where higher-priority tasks are those that act as pre-requisites or are more essential for meeting the objective.\nDo not remove any tasks. Return the ranked tasks as a numbered list in the format:\n\n#. First task\n#. Second task\n\nThe entries must be consecutively numbered, starting with 1. The number of each entry must be followed by a period.\nDo not include any headers before your ranked list or follow your list with any other output."""\n\n    print(f\'\\n****TASK PRIORITIZATION AGENT PROMPT****\\n{prompt}\\n\')\n    response = openai_call(prompt, max_tokens=2000)\n    print(f\'\\n****TASK PRIORITIZATION AGENT RESPONSE****\\n{response}\\n\')\n    if not response:\n        print(\'Received empty response from priotritization agent. Keeping task list unchanged.\')\n        return\n    new_tasks = response.split("\\n") if "\\n" in response else [response]\n    new_tasks_list = []\n    for task_string in new_tasks:\n        task_parts = task_string.strip().split(".", 1)\n        if len(task_parts) == 2:\n            task_id = \'\'.join(s for s in task_parts[0] if s.isnumeric())\n            task_name = re.sub(r\'[^\\w\\s_]+\', \'\', task_parts[1]).strip()\n            if task_name.strip():\n                new_tasks_list.append(\n                    {"task_id": task_id, "task_name": task_name})\n\n    return new_tasks_list\n\n\n# Execute a task based on the objective and five previous tasks\ndef execution_agent(objective: str, task: str) -> str:\n    """\n    Executes a task based on the given objective and previous context.\n\n    Args:\n        objective (str): The objective or goal for the AI to perform the task.\n        task (str): The task to be executed by the AI.\n\n    Returns:\n        str: The response generated by the AI for the given task.\n\n    """\n\n    context = context_agent(query=objective, top_results_num=5)\n    # print("\\n****RELEVANT CONTEXT****\\n")\n    # print(context)\n    # print(\'\')\n    prompt = f\'Perform one task based on the following objective: {objective}.\\n\'\n    if context:\n        prompt += \'Take into account these previously completed tasks:\' + \\\n            \'\\n\'.join(context)\n    prompt += f\'\\nYour task: {task}\\nResponse:\'\n    return openai_call(prompt, max_tokens=2000)\n\n\n# Get the top n completed tasks for the objective\ndef context_agent(query: str, top_results_num: int):\n    """\n    Retrieves context for a given query from an index of tasks.\n\n    Args:\n        query (str): The query or objective for retrieving context.\n        top_results_num (int): The number of top results to retrieve.\n\n    Returns:\n        list: A list of tasks as context for the given query, sorted by relevance.\n\n    """\n    results = results_storage.query(\n        query=query, top_results_num=top_results_num)\n    # print("****RESULTS****")\n    # print(results)\n    return results\n\n\n# Add the initial task if starting new objective\nif not JOIN_EXISTING_OBJECTIVE:\n    initial_task = {\n        "task_id": tasks_storage.next_task_id(),\n        "task_name": \'Develop a task list\'\n    }\n    tasks_storage.append(initial_task)\n\n\ndef main():\n    loop = True\n    while loop:\n        # As long as there are tasks in the storage...\n        if not tasks_storage.is_empty():\n            # Print the task list\n            print("\\033[95m\\033[1m" +\n                  "\\n*****TASK LIST*****\\n" + "\\033[0m\\033[0m")\n            for t in tasks_storage.get_task_names():\n                print(" \u2022 " + str(t))\n\n            # Step 1: Pull the first incomplete task\n            task = tasks_storage.popleft()\n            print("\\033[92m\\033[1m" +\n                  "\\n*****NEXT TASK*****\\n" + "\\033[0m\\033[0m")\n            print(str(task["task_name"]))\n\n            # Send to execution function to complete the task based on the context\n            result = execution_agent(OBJECTIVE, str(task["task_name"]))\n            print("\\033[93m\\033[1m" +\n                  "\\n*****TASK RESULT*****\\n" + "\\033[0m\\033[0m")\n            print(result)\n\n            # Step 2: Enrich result and store in the results storage\n            # This is where you should enrich the result if needed\n            enriched_result = {\n                "data": result\n            }\n            # extract the actual result from the dictionary\n            # since we don\'t do enrichment currently\n            # vector = enriched_result["data"]\n\n            result_id = f"result_{task[\'task_id\']}"\n\n            results_storage.add(task, result, result_id)\n\n            # Step 3: Create new tasks and re-prioritize task list\n            # only the main instance in cooperative mode does that\n            new_tasks = task_creation_agent(\n                OBJECTIVE,\n                enriched_result,\n                task["task_name"],\n                tasks_storage.get_task_names(),\n            )\n\n            print(\'Adding new tasks to task_storage\')\n            for new_task in new_tasks:\n                new_task.update({"task_id": tasks_storage.next_task_id()})\n                print(str(new_task))\n                tasks_storage.append(new_task)\n\n            if not JOIN_EXISTING_OBJECTIVE:\n                prioritized_tasks = prioritization_agent()\n                if prioritized_tasks:\n                    tasks_storage.replace(prioritized_tasks)\n\n            # Sleep a bit before checking the task list again\n            time.sleep(5)\n        else:\n            print(\'Done.\')\n            loop = False\n\n\nif __name__ == "__main__":\n    main()\n'})})}function u(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}}}]);